const ALL_FACETS: readonly RequestFacet[] = ["value", "condition", "callers", "flow"];

function predictedFacets(text: string): Set<RequestFacet> {
  return new Set(extractFacetRequirements(text).map((r) => r.facet));
}

describe("held-out facet set #6 (64 items, computed-value phrasing, DEVELOPMENT set, 2026-10-02)", () => {
  const scored = HELD_OUT.filter((item) => item.adjudicated);

  it("table shape and id uniqueness", () => {
    expect(HELD_OUT.length).toBe(64);
    expect(new Set(HELD_OUT.map((i) => i.id)).size).toBe(64);
    expect(scored.length).toBe(64);
  });

  it("per-facet precision/recall floors and negative false positives", () => {
    const stats: Record<RequestFacet, { tp: number; fp: number; fn: number }> = {
      value: { tp: 0, fp: 0, fn: 0 },
      condition: { tp: 0, fp: 0, fn: 0 },
      callers: { tp: 0, fp: 0, fn: 0 },
      flow: { tp: 0, fp: 0, fn: 0 },
    };
    let negativeFalsePositiveItems = 0;
    const misses: string[] = [];
    for (const item of scored) {
      const predicted = predictedFacets(item.text);
      if (item.negative) {
        if (predicted.size > 0) {
          negativeFalsePositiveItems += 1;
          misses.push(`NEG ${item.id} predicted=[${[...predicted].join(",")}] "${item.text}"`);
        }
        for (const facet of ALL_FACETS) if (predicted.has(facet)) stats[facet].fp += 1;
        continue;
      }
      const gold = new Set(item.facets);
      const tolerated = new Set(item.toleratedExtra);
      for (const facet of ALL_FACETS) {
        const g = gold.has(facet);
        const p = predicted.has(facet);
        if (g && p) stats[facet].tp += 1;
        else if (g && !p) {
          stats[facet].fn += 1;
          misses.push(`MISS ${item.id} [${facet}] "${item.text}"`);
        } else if (!g && p && !tolerated.has(facet)) {
          stats[facet].fp += 1;
          misses.push(`EXTRA ${item.id} [${facet}] "${item.text}"`);
        }
      }
    }
    const report: Record<string, { precision: number; recall: number; tp: number; fp: number; fn: number }> = {};
    for (const facet of ALL_FACETS) {
      const { tp, fp, fn } = stats[facet];
      report[facet] = { precision: tp + fp === 0 ? 1 : tp / (tp + fp), recall: tp + fn === 0 ? 1 : tp / (tp + fn), tp, fp, fn };
    }
    // eslint-disable-next-line no-console
    console.log("requestFacets held-out #6:", JSON.stringify(report), `negatives with a false facet: ${negativeFalsePositiveItems}`);
    // eslint-disable-next-line no-console
    if (misses.length > 0) console.log(misses.join("\n"));
    const floors: Record<RequestFacet, { recall: number; precision: number }> = {
      value: { recall: 0.9, precision: 0.95 },
      condition: { recall: 0.65, precision: 0.85 },
      callers: { recall: 0.6, precision: 0.95 },
      flow: { recall: 0.4, precision: 0.95 },
    };
    for (const facet of ALL_FACETS) {
      expect(report[facet]!.recall, facet).toBeGreaterThanOrEqual(floors[facet].recall);
      expect(report[facet]!.precision, facet).toBeGreaterThanOrEqual(floors[facet].precision);
    }
    expect(negativeFalsePositiveItems).toBeLessThanOrEqual(0);
  });
});
